/**
 * The rrule check: the recurrence rules of `/calendar` give exactly what RFC 5545's
 * examples list and what an independent implementation gives, across the
 * clock changes too.
 *
 * Six claims:
 *
 *  - every example of RFC 5545, 3.8.5.3, as transcribed from the RFC text,
 *    to the occurrence (`rfc-examples`) — one, whose listed 15:00 its own
 *    UNTIL rules out, with the rule's answer and a note in the fixture;
 *  - every vector of python-dateutil's rrule with zoneinfo, generated by
 *    `scripts/rrule-vectors.py`, to the instant (`reference-vectors`);
 *  - the vectors that cross a clock change, and the RFC's own words on a
 *    time in a gap and in a repeated hour (`dst`);
 *  - a window of a rule that repeats forever is the same occurrences as the
 *    full expansion cut to the window (`window`);
 *  - a rule's text survives formatting and parsing, and a value out of range
 *    is an error (`parse-format`);
 *  - RDATE adds, EXDATE takes away after COUNT has counted, and the start is
 *    always the first occurrence (`rdate-exdate`).
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import { formatRRule, instantOf, occurrences, parseDateValue, parseRRule, utcStamp, wallOf } from "../../src/calendar/index.js";
import { formatWall, wallMs } from "../../src/calendar/rrule.js";

interface Example {
  readonly name: string;
  readonly tzid: string;
  readonly dtstart: string;
  readonly rrule: string;
  readonly expected: readonly string[];
  readonly forever?: boolean;
  readonly exdate?: readonly string[];
}
interface Vector {
  readonly tzid: string;
  readonly dtstart: string;
  readonly rrule: string;
  readonly bounded: boolean;
  readonly expected: readonly string[];
}
interface Vectors {
  readonly generator: string;
  readonly dateutil: string;
  readonly crossingClockChange: number;
  readonly cases: readonly Vector[];
}

const here = dirname(fileURLToPath(import.meta.url));
const examples = (JSON.parse(readFileSync(join(here, "rfc5545-examples.json"), "utf8")) as { examples: Example[] }).examples;
const vectors = JSON.parse(readFileSync(join(here, "vectors.json"), "utf8")) as Vectors;

/** An iCal local date-time in a zone, as an instant. */
function local(value: string, zone: string): number {
  const w = parseDateValue(value).wall;
  return instantOf(wallMs(w.year, w.month, w.day, w.hour, w.minute, w.second), zone);
}

const HOUR = 3_600_000;

function expandVector(vector: Vector, range: Parameters<typeof occurrences>[1] = vector.bounded ? {} : { limit: vector.expected.length }): string[] {
  return occurrences({ start: local(vector.dtstart, vector.tzid), timeZone: vector.tzid, rule: vector.rrule }, range).map(utcStamp);
}

describe("rrule: RFC 5545", () => {
  it.each(examples.map((example) => [example.name, example] as const))("[claim:rfc-examples] %s", (_, example) => {
    const got = occurrences(
      { start: local(example.dtstart, example.tzid), timeZone: example.tzid, rule: example.rrule, exdates: (example.exdate ?? []).map((each) => local(each, example.tzid)) },
      example.forever === true ? { limit: example.expected.length } : {},
    ).map((t) => formatWall(wallOf(t, example.tzid)));
    expect(got).toEqual(example.expected);
  });

  it("[claim:rfc-examples] every example of 3.8.5.3 is in the fixture", () => {
    expect(examples.length).toBe(42);
    expect(new Set(examples.map((example) => example.rrule)).size).toBeGreaterThanOrEqual(40);
  });
});

describe("rrule: an independent reference", () => {
  it("[claim:reference-vectors] the vectors come from python-dateutil, and there are enough of them", () => {
    expect(vectors.generator).toBe("python-dateutil");
    expect(vectors.cases.length).toBeGreaterThanOrEqual(800);
    const frequencies = new Set(vectors.cases.map((vector) => /FREQ=(\w+)/.exec(vector.rrule)?.[1]));
    expect([...frequencies].sort()).toEqual(["DAILY", "HOURLY", "MINUTELY", "MONTHLY", "WEEKLY", "YEARLY"]);
  });

  it("[claim:reference-vectors] every vector, to the instant", () => {
    const wrong: string[] = [];
    for (const vector of vectors.cases) {
      const got = expandVector(vector);
      if (JSON.stringify(got) !== JSON.stringify(vector.expected)) wrong.push(`${vector.tzid} ${vector.dtstart} ${vector.rrule}: ${got.slice(0, 4).join(",")} / ${vector.expected.slice(0, 4).join(",")}`);
    }
    expect(wrong).toEqual([]);
  });
});

describe("rrule: daylight saving", () => {
  it("[claim:dst] the vectors that cross a clock change agree", () => {
    const crossing = vectors.cases.filter((vector) => {
      const zone = vector.tzid;
      const offsets = new Set(vector.expected.map((stamp) => wallOf(Date.UTC(+stamp.slice(0, 4), +stamp.slice(4, 6) - 1, +stamp.slice(6, 8), +stamp.slice(9, 11), +stamp.slice(11, 13), +stamp.slice(13, 15)), zone) - Date.UTC(+stamp.slice(0, 4), +stamp.slice(4, 6) - 1, +stamp.slice(6, 8), +stamp.slice(9, 11), +stamp.slice(11, 13), +stamp.slice(13, 15))));
      return offsets.size > 1;
    });
    expect(crossing.length).toBeGreaterThanOrEqual(100);
    expect(crossing.length).toBe(vectors.crossingClockChange);
    for (const vector of crossing) expect(expandVector(vector)).toEqual(vector.expected);
  });

  it("[claim:dst] a daily meeting keeps its wall clock across both changes", () => {
    const zone = "Europe/Budapest";
    const got = occurrences({ start: local("20260327T090000", zone), timeZone: zone, rule: "FREQ=DAILY;COUNT=4" }).map((t) => formatWall(wallOf(t, zone)));
    expect(got).toEqual(["20260327T090000", "20260328T090000", "20260329T090000", "20260330T090000"]);
    const autumn = occurrences({ start: local("20261024T090000", zone), timeZone: zone, rule: "FREQ=DAILY;COUNT=3" });
    expect(autumn.map((t, i) => (i === 0 ? 0 : t - (autumn[i - 1] ?? 0)))).toEqual([0, 25 * HOUR, 24 * HOUR]);
  });

  it("[claim:dst] a time in the spring gap is read with the offset before it (RFC 5545, 3.3.5)", () => {
    const zone = "America/New_York";
    // 2:30 does not exist on 8 March 2026: it is 2:30 EST, which is 3:30 EDT.
    const got = occurrences({ start: local("20260307T023000", zone), timeZone: zone, rule: "FREQ=DAILY;COUNT=3" });
    expect(got.map(utcStamp)).toEqual(["20260307T073000Z", "20260308T073000Z", "20260309T063000Z"]);
    expect(formatWall(wallOf(got[1] ?? 0, zone))).toBe("20260308T033000");
  });

  it("[claim:dst] a time in the repeated hour is the first of the two", () => {
    const zone = "America/New_York";
    const got = occurrences({ start: local("20261031T013000", zone), timeZone: zone, rule: "FREQ=DAILY;COUNT=2" });
    // 1:30 EDT on 1 November, not 1:30 EST an hour later.
    expect(got.map(utcStamp)).toEqual(["20261031T053000Z", "20261101T053000Z"]);
  });

  it("[claim:dst] two wall clocks on one instant are one occurrence, counted once", () => {
    const zone = "America/New_York";
    // 2:00 is in the gap and means 3:00 EDT — the same instant as 3:00 itself.
    const got = occurrences({ start: local("20260308T010000", zone), timeZone: zone, rule: "FREQ=HOURLY;COUNT=4" });
    expect(got.map((t) => formatWall(wallOf(t, zone)))).toEqual(["20260308T010000", "20260308T030000", "20260308T040000", "20260308T050000"]);
  });

  it("[claim:dst] a half-hour change (Lord Howe) keeps the wall clock", () => {
    const zone = "Australia/Lord_Howe";
    const got = occurrences({ start: local("20261003T120000", zone), timeZone: zone, rule: "FREQ=DAILY;COUNT=3" });
    expect(got.map((t) => formatWall(wallOf(t, zone)))).toEqual(["20261003T120000", "20261004T120000", "20261005T120000"]);
    expect((got[1] ?? 0) - (got[0] ?? 0)).toBe(23.5 * HOUR);
  });
});

describe("rrule: windows", () => {
  it("[claim:window] a window of a rule that repeats forever is the full expansion cut to it", () => {
    let checked = 0;
    for (const [n, vector] of vectors.cases.entries()) {
      if (vector.bounded || vector.expected.length < 8) continue;
      const stampMs = (s: string): number => Date.UTC(+s.slice(0, 4), +s.slice(4, 6) - 1, +s.slice(6, 8), +s.slice(9, 11), +s.slice(11, 13), +s.slice(13, 15));
      const a = 3 + (n % 4);
      const b = vector.expected.length - 1 - (n % 3);
      const from = stampMs(vector.expected[a] ?? "") - (n % 2);
      const to = stampMs(vector.expected[b] ?? "");
      expect(expandVector(vector, { from, to })).toEqual(vector.expected.slice(a, b));
      checked += 1;
    }
    expect(checked).toBeGreaterThanOrEqual(400);
  });

  it("[claim:window] a rule with neither COUNT nor UNTIL needs an end", () => {
    expect(() => occurrences({ start: 0, rule: "FREQ=DAILY" })).toThrow(RangeError);
    expect(occurrences({ start: 0, rule: "FREQ=DAILY" }, { limit: 3 })).toHaveLength(3);
    expect(occurrences({ start: 0, rule: "FREQ=YEARLY;BYMONTH=2;BYMONTHDAY=30" }, { to: Date.UTC(2100, 0, 1) })).toEqual([0]);
  });
});

describe("rrule: parsing and formatting", () => {
  it("[claim:parse-format] every vector's rule survives formatting and parsing", () => {
    for (const vector of vectors.cases) {
      // WKST=MO is the default and is not written, so the text is compared,
      // and what it means.
      const rule = parseRRule(vector.rrule);
      expect(formatRRule(parseRRule(formatRRule(rule)))).toBe(formatRRule(rule));
      expect(expandVector({ ...vector, rrule: formatRRule(rule) })).toEqual(vector.expected);
    }
  });

  it("[claim:parse-format] the RRULE: name, lower case, and an x-name are taken; UNTIL as a date and as a floating time", () => {
    expect(parseRRule("RRULE:freq=weekly;byday=mo,-1fr;x-foo=bar")).toEqual({ freq: "WEEKLY", byDay: [{ day: "MO" }, { day: "FR", n: -1 }] });
    expect(parseRRule("FREQ=DAILY;UNTIL=20261231").until).toEqual({ year: 2026, month: 12, day: 31 });
    expect(parseRRule("FREQ=DAILY;UNTIL=20261231T120000").until).toEqual({ year: 2026, month: 12, day: 31, hour: 12, minute: 0, second: 0 });
    expect(parseRRule("FREQ=DAILY;UNTIL=20261231T120000Z").until).toBe(Date.UTC(2026, 11, 31, 12));
    expect(formatRRule(parseRRule("FREQ=DAILY;UNTIL=20261231"))).toBe("FREQ=DAILY;UNTIL=20261231");
    expect(formatRRule({ freq: "MONTHLY", until: new Date(Date.UTC(2026, 0, 1)), wkst: "SU", interval: 2 })).toBe("FREQ=MONTHLY;INTERVAL=2;UNTIL=20260101T000000Z;WKST=SU");
  });

  it("[claim:parse-format] a value out of range, a missing FREQ, and COUNT with UNTIL are errors", () => {
    for (const bad of ["BYDAY=MO", "FREQ=FORTNIGHTLY", "FREQ=DAILY;BYHOUR=24", "FREQ=DAILY;BYMONTHDAY=0", "FREQ=DAILY;BYDAY=0MO", "FREQ=DAILY;INTERVAL=0", "FREQ=DAILY;COUNT=2;UNTIL=20260101", "FREQ=DAILY;WKST=XX", "FREQ=DAILY;BYMONTH=13", "FREQ", "FREQ=DAILY;UNTIL=2026"]) {
      expect(() => parseRRule(bad), bad).toThrow(SyntaxError);
    }
  });
});

describe("rrule: the recurrence set", () => {
  const zone = "Europe/Budapest";
  const start = local("20261102T100000", zone);

  it("[claim:rdate-exdate] RDATE adds, EXDATE takes away after COUNT counted it, duplicates are one", () => {
    const got = occurrences({ start, timeZone: zone, rule: "FREQ=DAILY;COUNT=4", rdates: [local("20261110T080000", zone), local("20261103T100000", zone)], exdates: [local("20261104T100000", zone)] });
    expect(got.map((t) => formatWall(wallOf(t, zone)))).toEqual(["20261102T100000", "20261103T100000", "20261105T100000", "20261110T080000"]);
  });

  it("[claim:rdate-exdate] the start is the first occurrence even when the rule would not give it, and COUNT counts it", () => {
    // 2 November 2026 is a Monday; the rule says Fridays.
    const got = occurrences({ start, timeZone: zone, rule: "FREQ=WEEKLY;BYDAY=FR;COUNT=3" });
    expect(got.map((t) => formatWall(wallOf(t, zone)))).toEqual(["20261102T100000", "20261106T100000", "20261113T100000"]);
  });

  it("[claim:rdate-exdate] without a rule, the set is the start and the extra dates, in the range", () => {
    const got = occurrences({ start, rdates: [start + HOUR, start - HOUR] }, { from: start, to: start + 2 * HOUR });
    expect(got).toEqual([start, start + HOUR]);
    expect(occurrences({ start, rule: "FREQ=DAILY;COUNT=10" }, { limit: 2 })).toHaveLength(2);
  });
});
